import re
from datetime import datetime

DAY_FIRST = True   # 03/04/2026 means 3 April when True, 4 March when False
FORMATS = ["%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y", "%d.%m.%Y", "%b %d, %Y", "%d %b %Y", "%B %d, %Y", "%d %B %Y"]
if not DAY_FIRST:
    FORMATS[1:1] = ["%m/%d/%Y", "%m-%d-%Y"]
NUMBER = re.compile(r"^[-+]?\s*[$€£]?\s*[-+]?\d{1,3}(,\d{3})*(\.\d+)?\s*%?$|^[-+]?\s*[$€£]?\s*[-+]?\d+(\.\d+)?\s*%?$")


def snake(name):
    return re.sub(r"[^a-z0-9]+", "_", name.strip().lower()).strip("_") or "column"


def as_date(text):
    for f in FORMATS:
        try:
            return datetime.strptime(text, f).strftime("%Y-%m-%d")
        except ValueError:
            pass
    return None


def as_number(text):
    t = text.replace(",", "").replace("$", "").replace("€", "").replace("£", "").replace(" ", "")
    pct = t.endswith("%")
    try:
        n = float(t.rstrip("%"))
    except ValueError:
        return None
    n = n / 100 if pct else n
    return int(n) if n == int(n) and not pct and "." not in t else n


def main(input_data):
    rows = input_data["rows"]
    if not rows:
        raise ValueError("The file has no rows")
    names, seen = [], {}
    for h in rows[0].keys():
        s = snake(h)
        seen[s] = seen.get(s, 0) + 1
        names.append(s if seen[s] == 1 else "%s_%d" % (s, seen[s]))
    fixed = [dict(zip(names, [(v or "").strip() if isinstance(v, str) else v for v in r.values()])) for r in rows]
    blank = sum(1 for r in fixed if not any(r.values()))
    fixed = [r for r in fixed if any(r.values())]
    kinds = {}
    for n in names:
        vals = [r[n] for r in fixed if r.get(n)]
        if vals and sum(1 for v in vals if as_date(v)) >= 0.8 * len(vals):
            kinds[n] = "date"
        elif vals and sum(1 for v in vals if NUMBER.match(v)) >= 0.8 * len(vals):
            kinds[n] = "number"
    changed = {n: 0 for n in kinds}
    for r in fixed:
        for n, kind in kinds.items():
            v = r.get(n)
            new = (as_date(v) if kind == "date" else as_number(v)) if v else v
            if new is not None and new != v:
                changed[n] += 1
                r[n] = new
    unique, dupes, keys = [], 0, set()
    for r in fixed:
        k = tuple(str(r[n]) for n in names)
        if k in keys:
            dupes += 1
        else:
            keys.add(k)
            unique.append(r)
    lines = ["# Clean-up report\n", "%d rows in, %d rows out." % (len(rows), len(unique)),
             "- %d blank row(s) removed" % blank, "- %d duplicate row(s) removed" % dupes,
             "- columns: " + ", ".join(names)]
    for n, kind in kinds.items():
        lines.append("- %s read as %s (%d value(s) rewritten)" % (n, kind, changed[n]))
    return {"rows": unique, "report": "\n".join(lines) + "\n"}
